import React, { useState } from 'react'
import Navbar from '../Components/Navbar'
import Footer from '../Components/Footer'
import { CartProvider, useCart } from 'react-use-cart'
import { Link } from 'react-router-dom';
import SingleFav from './SingleFav';

function MyFav() {
    const { addItem } = useCart();
    const [fav, setFav] = useState(
        JSON.parse(localStorage.getItem("favorites")) || []
    );
    const removeFav = (id) => {
        const newFav = fav.filter((item) => item.id != id);
        setFav(newFav);
        localStorage.setItem(
            "favorites",
            JSON.stringify(newFav)
        );

    };
    return (
        <div className='wish-list mt-0'>
            {fav.length == 0 ? (
                <div className='text-center'>
                    <img src="./assetss/images/slider/wish3.jpg" className='mt-0'></img>
                    <h2>Your WishList is Empty ❤️</h2>
                    <p>You haven't added any products to your favorites yet.</p>
                    <div>
                        <Link to="/products" className='btn btn-dark mb-5 start-shopping discover'>Discover Our Products</Link>
                    </div>

                </div>
            ) : (
                <div className="row">
                    {fav.map((item) => {
                        return (
                            <div className="col-sm-12 mt-5 col-md-6 col-xl-4  ">
                                <div className="card  product-card-fav product-card-me ">

                                    <div className='card-img div-img-fav'>
                                        <img
                                            src={item.images[0]}
                                            className="card-img-top position-relative"
                                            alt="Product Name"
                                        />
                                        <button className='product-fav-icon' onClick={() => removeFav(item.id)}>
                                            <i class="fa-solid fa-heart-circle-xmark"></i>
                                        </button>
                                        {/* <button className={`position-absolute heart ${fav.includes(item) ? "redheart" : ""}`} onClick={() => togglefav(item)}><i className="fa-solid fa-heart" ></i></button> */}

                                    </div>

                                    <div className="card-body ">
                                        <h5 className="  mb-2  text-sm  choose-button title">
                                            <Link to={`/detail/${item.id}`} className="title">{item.title}</Link>
                                            <div className=" choose-button">

                                                <div className="">

                                                    <span className="">${item.price}</span>
                                                </div>
                                            </div>

                                        </h5>
                                        <h5 className="  mb-2  text-sm  choose-button brand">
                                            Brand:
                                            <h6 className='text-muted'>{item.brand}</h6>
                                        </h5>
                                        <div className='allproducts-buttons'>

                                            <Link to={`/detail/${item.id}`} className="btn btn-primary btn-sm my-btn button-me ">
                                                Details
                                            </Link>
                                            <button onClick={() => addItem(item)} className="btn btn-primary btn-sm my-btn button-me addtocart ">
                                                Add to Cart
                                            </button>
                                        </div>

                                    </div>
                                </div>
                            </div>
                        )
                    })}
                </div>
            )
            }
        </div>
    )
}
function AllFav() {

    return (
        <div>
            <Navbar />
            <SingleFav />
            <MyFav />
            <Footer />
        </div>
    )
}

export default AllFav