import React, { useContext, useState } from 'react'
import Navbar from '../Components/Navbar'
import { CartProvider, useCart } from 'react-use-cart'
import ProductList from './ProductList'
import Footer from '../Components/Footer'
import { apiValue } from '../Data/AllData'
import { Link, NavLink } from 'react-router-dom'


function Products() {
    const { text, searchValue } = useContext(apiValue);
    const [sort, setSort] = useState("");
    const filteredData = text.filter((item) =>
        item.title.toLowerCase().includes(searchValue.toLowerCase())
    );
    const sortData = [...filteredData];

    if (sort == "low") {
        sortData.sort((a, b) => a.price - b.price);
    }
    if (sort == "high") {
        sortData.sort((a, b) => b.price - a.price);
    }
    if (sort == "az") {
        sortData.sort((a, b) => a.title.localeCompare(b.title));
    }
    if (sort == "za") {
        sortData.sort((a, b) => b.title.localeCompare(a.title));
    }
    const [search, Setsearch] = useState("All");
    const [active, setActive] = useState(0);


    const [fav, setFav] = useState(
        JSON.parse(localStorage.getItem("favorites")) || []
    );
    const { addItem } = useCart();
    const getValue = (name) => {
        Setsearch(name);
    }
    const togglefav = (item) => {
        const isFav = fav.some((favItem) => favItem.id == item.id);
        if (isFav) {
            const newFav = fav.filter((favarray) => favarray.id != item.id);
            setFav(newFav);
            localStorage.setItem("favorites", JSON.stringify(newFav));
        } else {
            const newFav = [...fav, item];
            setFav(newFav);
            localStorage.setItem("favorites", JSON.stringify(newFav));

        }

    }
    return (
        <section className="py-lg-8 py-5">
            <div className='sort-selection'>
                <h5>Sort Your Products:</h5>
                <select
                    value={sort}
                    onChange={(event) => setSort(event.target.value)}
                    className='select'
                >
                    <option value="" className='option-select'>Default</option>
                    <option value="low" className='option-select'>Price: Low to High</option>
                    <option value="high" className='option-select'>Price: High to Low</option>
                    <option value="az" className='option-select'>Name: A to Z</option>
                    <option value="za" className='option-select'>Name: Z to A</option>
                </select>
            </div>
            <div className="container m-auto  ">
                <div className='d-flex justify-content-center flex-wrap gap-2 col-12  '>
                    <button onClick={() => { getValue("All"); setActive(0); }} className={`btn btn-dark   my-btn-me choose-button ${active == 0 ? "active" : ""}`}   >All</button>
                    <button onClick={() => { getValue("Chairs"); setActive(1); }} className={`btn btn-dark my-btn-me choose-button ${active == 1 ? "active" : ""}`}>Chairs</button>
                    <button onClick={() => { getValue("Sofas"); setActive(2); }} className={`btn btn-dark  my-btn-me choose-button  ${active == 2 ? "active" : ""}`}>Sofas</button>
                    <button onClick={() => { getValue("Desks"); setActive(3); }} className={`btn btn-dark my-btn-me  choose-button  ${active == 3 ? "active" : ""}`} >Desks</button>
                    <button onClick={() => { getValue("Lighting"); setActive(4); }} className={`btn btn-dark my-btn-me choose-button  ${active == 4 ? "active" : ""}`}>Lighting</button>

                </div>
                <div className="row">
                    {filteredData.length === 0 && searchValue.trim() !== "" ? (
                        <div className="text-center py-5 searchValue">
                            <h3>No products found</h3>
                            <p>
                                We couldn't find any product matching "{searchValue}"
                            </p>
                        </div>) : (

                        sortData.map((item) => {
                            return search == "All" ? (
                                <div className="col-sm-12 mt-5 col-md-6 col-xl-4">
                                    <div className="card  product-card product-card-me">

                                        <div className='card-img'>
                                            <img
                                                src={item.images[0]}
                                                className="card-img-top position-relative"
                                                alt="Product Name"
                                            />
                                            <button className={`position-absolute heart ${fav.some((favItem) => favItem.id == item.id) ? "redheart" : ""}`} onClick={() => togglefav(item)}><i className="fa-solid fa-heart" ></i></button>

                                        </div>

                                        <div className="card-body">
                                            <h5 className="  mb-2  text-sm  choose-button title">
                                                <Link to={`/detail/${item.id}`} className="title">{item.title}</Link>
                                                <div className=" choose-button">

                                                    <div className="">

                                                        <span className="">${item.price}</span>
                                                    </div>
                                                </div>

                                            </h5>
                                            <h5 className="  mb-2  text-sm  choose-button brand">
                                                Brand:
                                                <h6 className='text-muted'>{item.brand}</h6>
                                            </h5>
                                            <div className='allproducts-buttons'>

                                                <Link to={`/detail/${item.id}`} className="btn btn-primary btn-sm my-btn button-me ">
                                                    Details
                                                </Link>
                                                <button onClick={() => addItem(item)} className="btn btn-primary btn-sm my-btn button-me ">
                                                    Add to Cart
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                            ) : item.category == search ? (
                                <div className="col-sm-12 mt-5 col-md-6 col-xl-4">
                                    <div className="card  product-card product-card-me">

                                        <div className='card-img'>
                                            <img
                                                src={item.images[0]}
                                                className="card-img-top"
                                                alt="Product Name"
                                            />
                                            <button className={`position-absolute heart ${fav.includes(item) ? "redheart" : ""}`} onClick={() => togglefav(item)}><i className="fa-solid fa-heart" ></i></button>

                                        </div>

                                        <div className="card-body">
                                            <h5 className="  mb-2  text-sm  choose-button title">
                                                <Link to={`/detail/${item.id}`} className="title">{item.title}</Link>
                                                <div className=" choose-button">

                                                    <div className="">

                                                        <span className="">${item.price}</span>
                                                    </div>
                                                </div>

                                            </h5>
                                            <h5 className="  mb-2  text-sm  choose-button brand">
                                                Brand:
                                                <h6 className='text-muted'>{item.brand}</h6>
                                            </h5>

                                            <div className='allproducts-buttons'>

                                                <Link to={`/detail/${item.id}`} className="btn btn-primary btn-sm my-btn button-me ">
                                                    Details
                                                </Link>
                                                <button onClick={() => addItem(item)} className="btn btn-primary btn-sm my-btn button-me ">
                                                    Add to Cart
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ) : null
                        })
                    )
                    }
                </div>
            </div>

        </section>

    )



}








function Allproducts() {
    return (
        <div>
            <Navbar />
            <ProductList />
            <Products />
            <Footer />
        </div>
    )
}

export default Allproducts