import React, { useState } from 'react'
import { CartProvider, useCart } from 'react-use-cart'
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';
import { Link } from 'react-router-dom';

function Cart() {
    const { items, totalItems, totalUniqueItems, updateItemQuantity, removeItem, isEmpty, emptyCart, cartTotal } = useCart();
    const [showConfirm, setShowConfirm] = useState(false);
    if (isEmpty) {
        return (
            <div className='text-center noproducts'>
                <img className='w-25' src="./assetss/images/emptycart.jpg"></img>
                <div >
                    <h2 className='cart-h2'>Your Cart Is Empty</h2>
                    <h5 className='text-muted '>Looks like you haven't added anything to your cart yet.</h5>
                    <Link className='btn btn-dark  start-shopping' to="/products" >
                        Start Shopping
                    </Link>

                </div>

            </div>
        )
    }


    return (
        <div>
            <section className="h-100 h-custom cart-sec" style={{ backgroundColor: "#ffffff00" }}>
                <div className="container py-5 h-100">
                    <div className="row d-flex justify-content-center align-items-center h-100">
                        <div className="col-12">
                            <div
                                className="card card-registration card-registration-2"
                                style={{ borderRadius: 15 }}
                            >
                                <div className="card-body p-0">
                                    <div className="row g-0">
                                        <div className="col-lg-8">
                                            <div className="p-5">
                                                <div className="d-flex justify-content-between align-items-center mb-5">
                                                    <h1 className="fw-bold mb-0 mr-5">Shopping Cart ({totalUniqueItems})</h1>

                                                    <button onClick={() => setShowConfirm(true)} className='border-0   rounded-2 btn btn-danger empty-dan '><i class="fa-solid fa-trash trash"></i>Clear All</button>
                                                </div>
                                                <hr className="my-4" />
                                                <div className="row mb-4 d-flex justify-content-between align-items-center">


                                                    {items.map((item) => {
                                                        return (
                                                            <div>

                                                                <div className="row mb-4 d-flex justify-content-between align-items-center">
                                                                    <div className="col-md-2 col-lg-2 col-xl-2">
                                                                        <Link to={`/detail/${item.id}`}>
                                                                            <img
                                                                                src={item.images[0]}
                                                                                className="img-fluid w-100"

                                                                            />
                                                                        </Link>
                                                                    </div>
                                                                    <div className="col-md-3 col-lg-3 col-xl-3">
                                                                        <Link to={`/detail/${item.id}`}>
                                                                            <h5 className=" title mb-2">{item.title}</h5>
                                                                        </Link>
                                                                        <h6 className="mb-2">Category:{item.category}</h6>
                                                                        <h6 className="mb-2">Brand:{item.brand}</h6>

                                                                    </div>
                                                                    <div className="col-md-3 col-lg-3 col-xl-2 d-flex">

                                                                        <button onClick={() => updateItemQuantity(item.id, item.quantity - 1)} className='btn btn-warning update-btn'>-</button>
                                                                        <h6 className='text-center mb-1 mr-2 d-flex align-items-center'>Quantity:<br></br>{item.quantity}</h6>
                                                                        <button onClick={() => updateItemQuantity(item.id, item.quantity + 1)} className='btn btn-success update-btn '>+</button>


                                                                    </div>
                                                                    <div className="col-md-3 col-lg-2 col-xl-2 offset-lg-1">
                                                                        <h6 className="mb-0">${Math.ceil(item.price * item.quantity)}</h6>
                                                                    </div>
                                                                    <div className="col-md-1 col-lg-1 col-xl-1 text-center">
                                                                        <button className=' remove-btn ' onClick={() => removeItem(item.id)}><i className="fa-solid fa-trash"></i></button>

                                                                    </div>
                                                                </div>
                                                                <hr className="my-4" />
                                                            </div>
                                                        )
                                                    })}


                                                    <div className="pt-5">
                                                        <div className='allproducts-buttons w-50'>

                                                            <Link to="/products" className="btn btn-primary btn-sm my-btn button-me mb-3 backtoshop ">
                                                                <i className="fas fa-long-arrow-alt-left me-2" /> Back To Shop
                                                            </Link>
                                                        </div>

                                                    </div>


                                                </div>
                                            </div>

                                        </div>

                                        <div className="col-lg-4 bg-body-tertiary summary-sec">
                                            <div className="p-5">
                                                <h3 className="fw-bold mb-5 mt-2 pt-1">Summary</h3>
                                                <hr className="my-4" />
                                                <div className="d-flex justify-content-between mb-4">
                                                    <h5>subtotal ({totalItems} items)</h5>
                                                    <h5>${cartTotal}</h5>
                                                </div>
                                                <h5 className="text-uppercase mb-3">Shipping</h5>
                                                <div className="mb-4 pb-2">

                                                    <span value={1}>Standard-Delivery- $70.00</span>


                                                </div>


                                                <hr className="my-4" />
                                                <div className="d-flex justify-content-between mb-5">
                                                    <h5 className="text-uppercase">Total price</h5>
                                                    <h5>${cartTotal + 70}</h5>
                                                </div>
                                                <button
                                                    type="button"
                                                    data-mdb-button-init=""
                                                    data-mdb-ripple-init=""
                                                    className="btn btn-dark btn-block btn-md register"
                                                    data-mdb-ripple-color="dark"
                                                >
                                                    Checkout
                                                </button>
                                                <Link to="/products"
                                                    type="button"
                                                    data-mdb-button-init=""
                                                    data-mdb-ripple-init=""
                                                    className="btn btn-dark btn-block btn-md register"
                                                    data-mdb-ripple-color="dark"
                                                >
                                                    <i className="fa-solid fa-arrows-turn-right  "></i>
                                                    Continue Shopping
                                                </Link>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
            {showConfirm && (
                <div className="confirm-overlay">

                    <div className="confirm-box">

                        <div className="confirm-icon">
                            <i class="fa-solid fa-trash"></i>
                        </div>

                        <h3>Clear Cart?</h3>

                        <p>
                            Are you sure you want to remove all items from your cart?
                        </p>

                        <div className="confirm-buttons">

                            <button
                                className="cancel-btn"
                                onClick={() => setShowConfirm(false)}
                            >
                                Cancel
                            </button>

                            <button
                                className="delete-btn"
                                onClick={() => {
                                    emptyCart();
                                    setShowConfirm(false);
                                }}
                            >
                                Yes, Clear All
                            </button>

                        </div>

                    </div>

                </div>
            )}

        </div>
    )

}
function AllCart() {
    return (
        <div>
            <Navbar />
            <Cart />
            <Footer />
        </div>
    )
}

export default AllCart
