import React, { use, useContext, useEffect, useState } from 'react'
import Navbar from '../Components/Navbar'
import Footer from '../Components/Footer'
import { Link, useParams } from 'react-router-dom'
import axios from 'axios';
import { apiValue } from '../Data/AllData';
import { CartProvider, useCart } from 'react-use-cart';
import SingleProductList from './SingleProductList';

function AllSingleProduct() {
    const { id } = useParams();
    const {text} = useContext(apiValue);
    const { addItem } = useCart();
    const [fav, setFav] = useState(
        JSON.parse(localStorage.getItem("favorites")) || []
    );
    const togglefav = (item) => {
        const isFav = fav.some((favItem) => favItem.id == item.id);
        if (isFav) {
            const newFav = fav.filter((favarray) => favarray.id != item.id);
            setFav(newFav);
            localStorage.setItem("favorites", JSON.stringify(newFav));
        } else {
            const newFav = [...fav, item];
            setFav(newFav);
            localStorage.setItem("favorites", JSON.stringify(newFav));

        }

    }

    return (
        <>
            <Navbar />
            <SingleProductList/>
            {text.map((item) => {
                return item.id == id ? (
                    <div className='container  mb-5 single-products'>
                        <div className='row'>
                            <div className='col-md-6 single-img-fav position-relative'>
                                <img className='w-100 h-100 ' src={item.images[0]}></img>
                                <button className={`heart ${fav.some((favItem) => favItem.id == item.id) ? "redheart" : ""}`} onClick={() => togglefav(item)}><i className="fa-solid fa-heart" ></i></button>
                            </div>
                            <div className='col-lg-6 singleproduct mt-5 '>
                                <span>Title:</span>

                                <h1 className='sentance'>{item.title}</h1>

                                <div className="text-secondary stars mb-2 fs-5">
                                    ★★★★★ 4.8(24 Reviews)
                                </div>
                                 <h2 className='item-price'>${item.price}</h2>
                                <h4 className='mb-5'>Find the perfect furniture for your home with modern designs, great quality, and affordable prices.</h4>
                                <span>Brand:</span> <h4 className='bold'>{item.brand}</h4>
                                <span>Category:</span> <h4 className='bold'>{item.category}</h4>
                                <div className='singleproduct-buttons'>
                                    {/* <Link to="/products" className="btn btn-primary back">
                                        <i className="fas fa-long-arrow-alt-left me-2" />
                                        Back</Link>
                                    <button onClick={() => addItem(item)} className="btn btn-primary back">
                                        <i class="fa-solid fa-cart-plus"></i> Add To Cart</button> */}
                                    <div className='allproducts-buttons'>

                                        <Link to="/products" className="btn btn-primary btn-sm my-btn button-me mb-3 "> 
                                            <i className="fas fa-long-arrow-alt-left me-2" /> Continue Shopping
                                        </Link>
                                        <button onClick={() => addItem(item)} className="btn btn-primary btn-sm my-btn button-me  ">
                                            <i class="fa-solid fa-cart-plus"></i> Add to Cart
                                        </button>

                                    </div>

                                </div>

                            </div>
                        </div>

                    </div>
                ) : null
            })}

            <Footer />

        </>

    )
}

export default AllSingleProduct