import React, { useState, useEffect, useContext } from 'react'
import { Link, Navigate, NavLink, useNavigate } from 'react-router-dom'
import { useCart } from 'react-use-cart'
import { apiValue } from '../Data/AllData';


function Navbar() {
  const { totalItems } = useCart();
  const [isDark, setDark] = useState(localStorage.getItem("theme") === "dark");
  const [showSearch, setShowSearch] = useState(false);
  const { searchValue, setSearchValue } = useContext(apiValue);
  const navigate=useNavigate();
  useEffect(() => {
    if (localStorage.getItem("theme") === "dark") {
      document.body.classList.add("dark");
    }
  }, []);
  const darkMode = () => {
    document.body.classList.toggle('dark');
    const dark = document.body.classList.contains('dark');
    setDark(dark);
    localStorage.setItem("theme", dark ? "dark" : "light");
  }
  return (
    <div className='nav-section'>
      <nav className="navbar navbar-expand-lg  shadow-sm px-4 py-3 navbar-custom">
        <div className="container-fluid px-0">
          <NavLink className="navbar-brand" to="/">
            <span className="d-flex flex-column text-uppercase text-xs fw-bold lh-sm">
              <span className="" style={{ letterSpacing: ".12rem" }}>
                Furnish
              </span>
              <span>Template</span>
            </span>
          </NavLink>
          <div className="mx-auto d-lg-block d-none">
            <ul className="navbar-nav me-auto mb-2 mb-lg-0">
              <li className="nav-item">
                <NavLink className="nav-link" aria-current="page" to="/">
                  Home
                </NavLink>
              </li>
              <li className="nav-item">
                <NavLink className="nav-link" to="/about">
                  About us
                </NavLink>
              </li>
              <li className="nav-item">
                <NavLink className="nav-link" to="/products">
                  Products
                </NavLink>
              </li>
              <li className="nav-item">
                <NavLink className="nav-link" to="/fav">
                  Favoirtes
                </NavLink>
              </li>
              <li className="nav-item">
                <NavLink className="nav-link" to="/test">
                  Testimonials
                </NavLink>
              </li>
              <li className="nav-item">
                <NavLink className="nav-link " to="/contact">
                  Contact
                </NavLink>
              </li>
            </ul>
          </div>
          <div className="d-flex align-items-center gap-4">
            <span className="d-flex align-items-center gap-2 fw-bold">

              <div className={`nav-search ${showSearch ? "active" : ""}`}>

                <i
                  className="fa-solid fa-magnifying-glass search-icon"
                  onClick={() => setShowSearch(!showSearch)}
                ></i>

                {showSearch && (
                  <input
                    type="text"
                    placeholder="Search products..."
                    value={searchValue}
                    onChange={(event) => setSearchValue(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        navigate("/products");
                      }
                    }}
                    autoFocus
                  />
                )}
              </div>

              <div className='dark-color'>
                <button onClick={darkMode}>
                  <i className={isDark ? "bi bi-sun-fill" : " bi bi-moon-fill"} style={{ transition: ".4s" }}></i>
                </button>
              </div>
              <span className="nav-item">
                <NavLink className="nav-link position-relative iconn" to="/cart">

                  <i class="fa-solid fa-cart-shopping"></i>
                  <span className='cart-badge'>{totalItems}</span>



                </NavLink>
              </span>
              <span className='tele'>
                <i className="bi bi-telephone" />
              </span>
              <span className='tele'>+901234576</span>
            </span>
            <a
              className="menu-toggle"
              href="#offcanvasExample"
              data-bs-toggle="offcanvas"
              role="button"
              aria-controls="offcanvasExample"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                fill="currentColor"
                className="bi bi-list"
                viewBox="0 0 16 16"
              >
                <path
                  fillRule="evenodd"
                  d="M2.5 12a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5m0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5m0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5"
                />
              </svg>
            </a>
          </div>
        </div >
      </nav >

      <div

        className="offcanvas offcanvas-end nav-section-menu"
        data-bs-backdrop="false"
        tabIndex="-1"
        id="offcanvasExample"
        aria-labelledby="offcanvasExampleLabel"
      >
        <div className="offcanvas-header">
          <h5 id="offcanvasExampleLabel">Furnish</h5>

          <button
            type="button"
            className="btn-close"
            data-bs-dismiss="offcanvas"
            aria-label="Close"
          ></button>
        </div>

        <div className="offcanvas-body navbarr-custom">
          <ul className="navbar-nav">
            <li className="nav-item">
              <NavLink className="nav-link" aria-current="page" to="/">
                Home
              </NavLink>
            </li>

            <li className="nav-item">
              <NavLink className="nav-link" to="/about">
                About us
              </NavLink>
            </li>

            <li className="nav-item">
              <NavLink className="nav-link" to="/products">
                Products
              </NavLink>
            </li>
            <li className="nav-item">
              <NavLink className="nav-link" to="/fav">
                Favoirtes
              </NavLink>
            </li>
            <li className="nav-item">
              <NavLink className="nav-link" to="/test">
                Testimonials
              </NavLink>
            </li>

            <li className="nav-item">
              <NavLink className="nav-link " to="/contact">
                Contact
              </NavLink>
            </li>
          </ul>
        </div>
      </div>
    </div >

  )
}

export default Navbar