
import ReactDOM from 'react-dom/client';
import "./assets/scss/style.scss";
import App from './App';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import "bootstrap-icons/font/bootstrap-icons.css";
import AllCart from './Cart/AllCart';
import { AllData } from './Data/AllData';
import ScrollToTop from 'react-scroll-to-top';
import AllAbout from './About/AllAbout';
import AllTestimonials from './Testimonials/AllTestimonials';
import ContactUS from './Contact/ContactUS';
import Allproducts from './Products/Allproducts';
import AllSingleProduct from './SingleProduct/AllSingleProduct';
import "bootstrap/dist/js/bootstrap.bundle.min.js";
import AllFav from './Fav/AllFav';
import { CartProvider } from 'react-use-cart';



const x = createBrowserRouter(
  [
    {
      path: "/",
      element: <App />
    },
    {
      path: "about",
      element: <AllAbout />
    },
    {
      path: "test",
      element: <AllTestimonials />
    },
    {
      path: "contact",
      element: <ContactUS />
    },
    {
      path: "products",
      element: <Allproducts />
    },
    {
      path: "fav",
      element: <AllFav />
    },
    {
      path: "detail/:id",
      element: <AllSingleProduct />
    },
    {
      path: "cart",
      element: <AllCart />
    },
  ]
);

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <AllData>
    <CartProvider>
      <ScrollToTop smooth style={{ color: "#000" }} />
      <RouterProvider router={x} />

    </CartProvider>

  </AllData>




);


